package com.example.project_ballin

/**
 * A class that stores information about a report
 * that either a user can make or is generated by the system
 *
 * @property reason the reason for the report
 * @property reportSubject the subject of the report
 * @property ID the unique ID of the report
 * @property idBeingReported the ID of the owner/review/rating being reported
 */
class Report (
    var reason: String = "",
    var reportSubject: String = "",
    var idBeingReported: String = "",
    var ID: String = ""
)